-- Each built-in exercise's primary and secondary muscles, stability demand, joint load
-- and how its sets are logged. Generated by scripts/exercise-attributes.ts from
-- supabase/data/exercise-attributes.json; edit the JSON, not this file. Applied by hand in
-- the SQL Editor.
--
-- Values come from the fixed vocabularies in lib/exercise-attributes.ts, enforced by
-- check constraints. Custom exercises keep empty muscle arrays (and fall back to
-- muscle_group) and are logged as weight x reps.
--
-- It is one DO block, so it applies all or nothing, and it is safe to run twice.

do $$
declare
    v_missing int;
begin
    alter table exercises add column if not exists primary_muscles text[] not null default '{}';
    alter table exercises add column if not exists secondary_muscles text[] not null default '{}';
    alter table exercises add column if not exists stability_demand text;
    alter table exercises add column if not exists joint_load jsonb;
    alter table exercises add column if not exists log_type text not null default 'weight_reps';

    alter table exercises drop constraint if exists exercises_muscles_known;
    alter table exercises add constraint exercises_muscles_known check (
        primary_muscles <@ array['chest', 'upper_chest', 'lower_chest', 'front_delts', 'side_delts', 'rear_delts', 'lats', 'upper_back', 'traps', 'lower_back', 'biceps', 'triceps', 'forearms', 'quads', 'hamstrings', 'adductors', 'calves', 'glutes', 'abductors', 'abs', 'obliques', 'cardio']::text[]
        and secondary_muscles <@ array['chest', 'upper_chest', 'lower_chest', 'front_delts', 'side_delts', 'rear_delts', 'lats', 'upper_back', 'traps', 'lower_back', 'biceps', 'triceps', 'forearms', 'quads', 'hamstrings', 'adductors', 'calves', 'glutes', 'abductors', 'abs', 'obliques', 'cardio']::text[]
    );
    alter table exercises drop constraint if exists exercises_stability_demand_known;
    alter table exercises add constraint exercises_stability_demand_known check (stability_demand in ('low', 'medium', 'high'));
    alter table exercises drop constraint if exists exercises_log_type_known;
    alter table exercises add constraint exercises_log_type_known check (log_type in ('weight_reps', 'bodyweight', 'assisted', 'duration', 'treadmill', 'cardio_level', 'rower', 'cardio_time'));

    update exercises e
    set primary_muscles = v.primary_muscles,
        secondary_muscles = v.secondary_muscles,
        stability_demand = v.stability_demand,
        joint_load = v.joint_load,
        log_type = v.log_type
    from (values
        -- Assisted Pull-up
        ('b1f735c6-9359-53d8-92ba-492d7b3b74c1', '{lats}'::text[], '{biceps,upper_back,forearms}'::text[], 'low', '{"shoulder":"medium","elbow":"low","lower_back":"low","knee":"low"}'::jsonb, 'assisted'),
        -- Back Extension
        ('9ffc05c4-965a-5769-b0a2-3eb1c2799ec5', '{lower_back}'::text[], '{glutes,hamstrings}'::text[], 'low', '{"shoulder":"low","elbow":"low","lower_back":"medium","knee":"low"}'::jsonb, 'bodyweight'),
        -- Barbell Row
        ('a03bba95-1574-4ac2-a204-5e4d547711ec', '{lats,upper_back}'::text[], '{rear_delts,biceps,lower_back,forearms}'::text[], 'medium', '{"shoulder":"low","elbow":"low","lower_back":"medium","knee":"low"}'::jsonb, 'weight_reps'),
        -- Barbell Shrug
        ('cec4fc59-2312-52cb-a4e2-68519ece446e', '{traps}'::text[], '{forearms}'::text[], 'medium', '{"shoulder":"low","elbow":"low","lower_back":"low","knee":"low"}'::jsonb, 'weight_reps'),
        -- Chest Supported Row
        ('835d1d13-10e5-4505-aeed-af6c2c191f79', '{upper_back,lats}'::text[], '{rear_delts,biceps,forearms}'::text[], 'low', '{"shoulder":"low","elbow":"low","lower_back":"low","knee":"low"}'::jsonb, 'weight_reps'),
        -- Chin-up
        ('d9481455-4292-4125-90d5-f52a83266f5b', '{lats}'::text[], '{biceps,upper_back,forearms}'::text[], 'high', '{"shoulder":"medium","elbow":"medium","lower_back":"low","knee":"low"}'::jsonb, 'bodyweight'),
        -- Close Grip Lat Pulldown
        ('0ecb7835-60d5-416c-8f24-47cdb6bcda1f', '{lats}'::text[], '{biceps,upper_back,forearms}'::text[], 'low', '{"shoulder":"low","elbow":"low","lower_back":"low","knee":"low"}'::jsonb, 'weight_reps'),
        -- Dumbbell Shrug
        ('9a4c755e-96c2-4931-8f25-a7a243b694cf', '{traps}'::text[], '{forearms}'::text[], 'medium', '{"shoulder":"low","elbow":"low","lower_back":"low","knee":"low"}'::jsonb, 'weight_reps'),
        -- Inverted Row
        ('49d93e9a-1046-55ef-b402-ad802775815c', '{upper_back,lats}'::text[], '{biceps,rear_delts,forearms}'::text[], 'medium', '{"shoulder":"low","elbow":"low","lower_back":"low","knee":"low"}'::jsonb, 'bodyweight'),
        -- Lat Pulldown
        ('9d187d17-8fc0-477d-a9f4-779df048b0ce', '{lats}'::text[], '{biceps,upper_back,forearms}'::text[], 'low', '{"shoulder":"low","elbow":"low","lower_back":"low","knee":"low"}'::jsonb, 'weight_reps'),
