        -- Rack Pull
        ('bbbb1576-240e-4692-909c-e7931c3a835b', '{lower_back,traps}'::text[], '{glutes,hamstrings,forearms}'::text[], 'medium', '{"shoulder":"low","elbow":"low","lower_back":"high","knee":"low"}'::jsonb, 'weight_reps'),
